package com.yeyamo_mobile.api.feed_service.infrastructure.persistence;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface SpringFeedSignalRepository extends JpaRepository<FeedSignalEntity,UUID>{Optional<FeedSignalEntity>findByUserIdAndPostId(String u,UUID p);@Query("select p.authorId,sum(s.weight) from FeedSignalEntity s join FeedPostEntity p on p.postId=s.postId where s.userId=:user group by p.authorId")List<Object[]>authorAffinities(@Param("user")String user);}
